lookup.day_rate:
// proration_basis WORKING_DAYS: no statute fixes it. 労働基準法 arts.24, 89(ii) leave an incomplete month to the work rules and 民法 art.624 pays for work done, so a scheduled working day is the unit.
// 労働基準法 art.37, 施行規則 art.19, art.21: monthly pay over scheduled monthly hours, fixed and attendance allowances in.
const terms = ctx.subject.employment.terms;
const unit = get(terms, 'rate.unit', 'MONTHLY');
const amount = Number(get(terms, 'rate.amount', 0));
const daily = Number(get(terms, 'normal_hours_per_day', 8));
const weekly = Number(
	get(terms, 'normal_hours_per_week', daily * Number(get(terms, 'normal_days_per_week', 5)))
);
const monthly = Number(get(terms, 'normal_hours_per_month', (weekly * 52) / 12));
if (!(monthly > 0)) return 0;
const allowances =
	Number(get(terms, 'allowances.FIXED_ALLOWANCE.amount', 0)) +
	Number(get(terms, 'allowances.ATTENDANCE_ALLOWANCE.amount', 0));
const hourly =
	unit === 'HOURLY' ? amount : unit === 'DAILY' ? (daily > 0 ? amount / daily : 0) : amount / monthly;
return (hourly + allowances / monthly) * daily;
